import { InvalidTransitionError, ValidationError } from "./errors";
import { assertPositiveInteger } from "./product";

export const ORDER_STATES = [
  "placed",
  "paid",
  "packed",
  "shipped",
  "delivered",
  "cancelled",
] as const;

export type OrderState = (typeof ORDER_STATES)[number];

/** The forward-only fulfilment sequence. */
const FULFILMENT_SEQUENCE: readonly OrderState[] = [
  "placed",
  "paid",
  "packed",
  "shipped",
  "delivered",
];

const CANCELLABLE_STATES: ReadonlySet<OrderState> = new Set<OrderState>([
  "placed",
  "paid",
  "packed",
]);

export function isOrderState(value: unknown): value is OrderState {
  return typeof value === "string" && (ORDER_STATES as readonly string[]).includes(value);
}

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
  readonly unitPriceCents: number;
}

export interface StateChange {
  readonly state: OrderState;
  readonly at: Date;
}

export interface OrderSnapshot {
  readonly id: string;
  readonly customerId: string;
  readonly state: OrderState;
  readonly lines: readonly OrderLine[];
  readonly totalCents: number;
  readonly history: readonly { state: OrderState; at: string }[];
  readonly createdAt: string;
  readonly updatedAt: string;
}

export class Order {
  private _state: OrderState = "placed";
  private readonly _history: StateChange[];
  readonly lines: readonly OrderLine[];

  constructor(
    readonly id: string,
    readonly customerId: string,
    lines: readonly OrderLine[],
    readonly createdAt: Date,
  ) {
    if (!customerId.trim()) throw new ValidationError("customerId must not be empty");
    if (lines.length === 0) throw new ValidationError("An order must contain at least one line");
    const seen = new Set<string>();
    for (const line of lines) {
      assertPositiveInteger(line.quantity, "quantity");
      if (seen.has(line.productId)) {
        throw new ValidationError(`Duplicate line for product ${line.productId}`);
      }
      seen.add(line.productId);
    }
    this.lines = lines.map((l) => ({ ...l }));
    this._history = [{ state: "placed", at: createdAt }];
  }

  get state(): OrderState {
    return this._state;
  }

  get history(): readonly StateChange[] {
    return this._history;
  }

  get totalCents(): number {
    return this.lines.reduce((sum, l) => sum + l.quantity * l.unitPriceCents, 0);
  }

  get updatedAt(): Date {
    return this._history[this._history.length - 1]!.at;
  }

  /** Returns the state that follows the current one, if any. */
  nextState(): OrderState | undefined {
    const index = FULFILMENT_SEQUENCE.indexOf(this._state);
    if (index === -1) return undefined;
    return FULFILMENT_SEQUENCE[index + 1];
  }

  canCancel(): boolean {
    return CANCELLABLE_STATES.has(this._state);
  }

  /** Moves the order to `target`, which must be the immediate next state. */
  advanceTo(target: OrderState, at: Date): void {
    if (target === "cancelled") {
      this.cancel(at);
      return;
    }
    const next = this.nextState();
    if (next !== target) {
      throw new InvalidTransitionError(
        `Cannot move order ${this.id} from '${this._state}' to '${target}'` +
          (next ? `; next allowed state is '${next}'` : "; no further transitions are allowed"),
      );
    }
    this.record(target, at);
  }

  cancel(at: Date): void {
    if (!this.canCancel()) {
      throw new InvalidTransitionError(
        `Cannot cancel order ${this.id} in state '${this._state}'; only orders not yet shipped can be cancelled`,
      );
    }
    this.record("cancelled", at);
  }

  toSnapshot(): OrderSnapshot {
    return {
      id: this.id,
      customerId: this.customerId,
      state: this._state,
      lines: this.lines.map((l) => ({ ...l })),
      totalCents: this.totalCents,
      history: this._history.map((h) => ({ state: h.state, at: h.at.toISOString() })),
      createdAt: this.createdAt.toISOString(),
      updatedAt: this.updatedAt.toISOString(),
    };
  }

  private record(state: OrderState, at: Date): void {
    this._state = state;
    this._history.push({ state, at });
  }
}

